{
  "name": "合成轴仿真组件",
  "name_en": "Synthetic Axis Simulation Component",
  "manufacturer": "",
  "description": "这是一个非物理的软件模拟组件，源自 ophyd 的 sim 模块。其核心类 SynAxis 用于模拟一维可设定轴，例如位置轴或温度轴，并可配合合成信号、周期更新、伪 EPICS 信号和简单扫描/采集接口，用于实验控制程序、扫描流程和数据采集逻辑的测试与演示。",
  "description_en": "This is a non-physical software simulation component derived from ophyd's sim module. Its core class, SynAxis, simulates a settable 1D axis such as position or temperature, and can be used with synthetic signals, periodic updates, fake EPICS-like signals, and simple scan/acquisition interfaces for testing and demonstrating experiment control, scan plans, and data acquisition logic.",
  "actions": [
    {
      "action_name": "auto-set",
      "description": "设置模拟轴的目标值。",
      "description_en": "Set the target value of the simulated axis."
    },
    {
      "action_name": "auto-put",
      "description": "写入模拟信号的值。",
      "description_en": "Write a value to a synthetic signal."
    },
    {
      "action_name": "auto-get",
      "description": "读取当前模拟值。",
      "description_en": "Get the current simulated value."
    },
    {
      "action_name": "auto-describe",
      "description": "获取该模拟组件数据字段的描述信息。",
      "description_en": "Describe the data fields exposed by this simulation component."
    },
    {
      "action_name": "auto-trigger",
      "description": "触发一次模拟更新或生成一次模拟读数。",
      "description_en": "Trigger a simulated update or generate one synthetic reading."
    },
    {
      "action_name": "auto-sim_set_func",
      "description": "定义用于生成模拟值的函数。",
      "description_en": "Define the function used to generate simulated values."
    },
    {
      "action_name": "auto-start_simulation",
      "description": "启动后台周期性模拟更新。",
      "description_en": "Start background periodic simulation updates."
    },
    {
      "action_name": "auto-read",
      "description": "读取当前模拟数据。",
      "description_en": "Read the current simulated data."
    },
    {
      "action_name": "auto-subscribe",
      "description": "订阅模拟值或状态变化通知。",
      "description_en": "Subscribe to simulated value or status change notifications."
    },
    {
      "action_name": "auto-timestamp",
      "description": "获取最近一次模拟更新的时间戳。",
      "description_en": "Get the timestamp of the most recent simulated update."
    },
    {
      "action_name": "auto-position",
      "description": "获取位置。",
      "description_en": "Get position."
    },
    {
      "action_name": "auto-hints",
      "description": "获取提示元数据。",
      "description_en": "Get hint metadata."
    },
    {
      "action_name": "auto-clear_sub",
      "description": "清除指定的订阅回调。",
      "description_en": "Clear a specified subscription callback."
    },
    {
      "action_name": "auto-unsubscribe",
      "description": "取消指定订阅。",
      "description_en": "Unsubscribe a specified callback."
    },
    {
      "action_name": "auto-unsubscribe_all",
      "description": "取消全部订阅。",
      "description_en": "Unsubscribe all callbacks."
    },
    {
      "action_name": "auto-precision",
      "description": "获取精度。",
      "description_en": "Get precision."
    },
    {
      "action_name": "auto-exposure_time",
      "description": "获取曝光时间。",
      "description_en": "Get exposure time."
    },
    {
      "action_name": "auto-kickoff",
      "description": "启动一次异步模拟扫描或采集过程。",
      "description_en": "Start an asynchronous simulated scan or acquisition process."
    },
    {
      "action_name": "auto-describe_collect",
      "description": "获取采集输出数据结构的描述信息。",
      "description_en": "Describe the structure of collected output data."
    },
    {
      "action_name": "auto-read_configuration",
      "description": "读取当前模拟配置。",
      "description_en": "Read the current simulation configuration."
    },
    {
      "action_name": "auto-describe_configuration",
      "description": "获取模拟配置字段的描述信息。",
      "description_en": "Describe the simulation configuration fields."
    },
    {
      "action_name": "auto-complete",
      "description": "完成当前异步模拟过程。",
      "description_en": "Complete the current asynchronous simulation process."
    },
    {
      "action_name": "auto-collect",
      "description": "收集缓冲的模拟数据。",
      "description_en": "Collect buffered simulated data."
    },
    {
      "action_name": "auto-collect_asset_docs",
      "description": "收集与模拟数据相关的资产文档。",
      "description_en": "Collect asset documents associated with simulated data."
    },
    {
      "action_name": "auto-stage",
      "description": "为一次实验运行准备该模拟组件。",
      "description_en": "Stage the simulation component for a run."
    },
    {
      "action_name": "auto-unstage",
      "description": "将该模拟组件恢复到未准备状态。",
      "description_en": "Unstage the simulation component back to its idle state."
    },
    {
      "action_name": "auto-get_file_list",
      "description": "获取模拟生成的数据文件列表。",
      "description_en": "Get the list of data files generated by the simulation."
    },
    {
      "action_name": "auto-forward",
      "description": "执行伪坐标到实坐标的前向变换。",
      "description_en": "Perform forward transformation from pseudo coordinates to real coordinates."
    },
    {
      "action_name": "auto-inverse",
      "description": "执行实坐标到伪坐标的逆向变换。",
      "description_en": "Perform inverse transformation from real coordinates to pseudo coordinates."
    },
    {
      "action_name": "auto-sim_set_putter",
      "description": "定义模拟写入操作的处理函数。",
      "description_en": "Define the handler used for simulated put operations."
    },
    {
      "action_name": "auto-sim_put",
      "description": "模拟一次外部写入以更新信号值。",
      "description_en": "Simulate an external put to update the signal value."
    },
    {
      "action_name": "auto-enum_strs",
      "description": "获取枚举字符串列表。",
      "description_en": "Get the list of enum strings."
    },
    {
      "action_name": "auto-sim_set_enum_strs",
      "description": "定义枚举字符串列表。",
      "description_en": "Define the list of enum strings."
    },
    {
      "action_name": "auto-limits",
      "description": "获取数值范围限制。",
      "description_en": "Get the value limits."
    },
    {
      "action_name": "auto-sim_set_limits",
      "description": "定义数值范围限制。",
      "description_en": "Define the value limits."
    },
    {
      "action_name": "auto-check_value",
      "description": "检查给定值是否符合模拟规则或范围限制。",
      "description_en": "Check whether a proposed value satisfies simulation rules or limits."
    }
  ],
  "tag_hints": [
    "synthetic axis simulation",
    "non-physical test device",
    "ophyd sim",
    "bluesky plan testing",
    "1D position/temperature emulation",
    "synthetic signal generation",
    "fake EPICS signal"
  ]
}

